// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MultiplicatorX3 c;
    Recorder rec;

    function setUp() public {
        c = new MultiplicatorX3();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount < 1e30);
        vm.assume(seed > 0 && seed < 1e30);
        // pre-existing balance in c, unrelated to msg.value of Command
        vm.deal(address(c), seed);
        vm.deal(address(this), amount);
        // Owner is the deployer (this test contract), so call directly
        c.Command{value: amount}(address(rec), "");
        // General rule: the callee received exactly the attached msg.value
        assertTrue(rec.received() == amount);
    }

    receive() external payable {}
}

contract Recorder {
    uint256 public received;
    receive() external payable {
        received += msg.value;
    }
}
